$('closeSheet').onclick=closeSheet;$('sheetOverlay').onclick=function(e){if(e.target===this)closeSheet();};document.addEventListener('keydown',function(e){if(e.key==='Escape'&&!$('sheetOverlay').hidden){closeSheet();e.preventDefault();}if(e.key==='Tab'&&!$('sheetOverlay').hidden){var focusable=Array.from($('sheet').querySelectorAll('button,input,textarea,select,[tabindex="0"]')).filter(function(n){return !n.disabled&&!n.hidden&&n.offsetParent!==null;}),first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('sheet'))){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
$('minimizeRecord').onclick=minimizeRecord;$('recordingBanner').onclick=showRecording;$('pauseRecording').onclick=function(){call('pauseRecord',{id:recordId}).catch(fail);};$('finishRecording').onclick=function(){this.disabled=true;$('pauseRecording').disabled=true;call('stopRecord',{id:recordId}).catch(function(e){$('finishRecording').disabled=false;fail(e);});};
var pollTimer=0;function schedule(){clearInterval(pollTimer);if(!document.hidden&&viewActive){poll(true);pollTimer=setInterval(function(){poll(false);},2000);if(!$('recordingScreen').hidden)drawWave();}else cancelAnimationFrame(waveFrame);}document.addEventListener('visibilitychange',schedule);window.addEventListener('resize',function(){if(!$('recordingScreen').hidden)drawWave();});
hydrate(document);if(native){native.ready();schedule();}else{$('libraryList').replaceChildren(el('p','loading-line',_t('Откройте Pocket Llama на телефоне.')));} 
